K2 = KRrt-KNrt_1-KPrt_1;
C2 = CRrt-CNrt_1-CPrt_1;
K1 = KRrt-K2;
C1 = CRrt-C2;

al = (4*MRrt+2*dt*CRrt+dt^2*KRrt)\MRrt*4;

S = zeros(2, 18);

